from html.parser import HTMLParser
from pathlib import Path
import subprocess, tempfile, os, sys
files=['dang-tin-tuyen-dung.html','dang-tin-viec-lam.html','nha-tuyen-dung.html','quan-ly-tin-tuyen-dung.html','ung-tuyen.html','tuyen-dung.html']
class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_script=False; self.script_attrs=None; self.scripts=[]; self.ids={}
    def handle_starttag(self, tag, attrs):
        ad=dict(attrs)
        if 'id' in ad:
            self.ids.setdefault(ad['id'],0); self.ids[ad['id']]+=1
        if tag.lower()=='script':
            self.in_script=True; self.script_attrs=ad; self._buf=[]
    def handle_endtag(self, tag):
        if tag.lower()=='script' and self.in_script:
            self.scripts.append((self.script_attrs,''.join(self._buf)))
            self.in_script=False; self.script_attrs=None; self._buf=[]
    def handle_data(self, data):
        if self.in_script: self._buf.append(data)
errors=0
for f in files:
    p=Path(f)
    if not p.exists(): continue
    parser=Parser(); parser.feed(p.read_text(encoding='utf-8', errors='replace'))
    dup={k:v for k,v in parser.ids.items() if v>1}
    print(f'## {f}: inline_scripts={sum(1 for a,s in parser.scripts if not a.get("src"))} duplicate_ids={dup or "none"}')
    for idx,(attrs,code) in enumerate(parser.scripts,1):
        if attrs.get('src') or not code.strip(): continue
        with tempfile.NamedTemporaryFile('w',suffix='.js',delete=False,encoding='utf-8') as tmp:
            tmp.write(code); name=tmp.name
        try:
