            if cp.returncode:
                errors+=1
                print(f'JS_CHECK_FAIL {f} script#{idx}')
                print(cp.stderr.strip() or cp.stdout.strip())
            else:
                print(f'JS_CHECK_OK {f} script#{idx}')
        finally:
            os.unlink(name)
if errors:
    sys.exit(1)
