from html.parser import HTMLParser
from pathlib import Path
import os, re, subprocess, sys, tempfile

class Parser(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_script=False; self.attrs=None; self.scripts=[]; self.ids={}
    def handle_starttag(self, tag, attrs):
        ad=dict(attrs)
        if 'id' in ad: self.ids[ad['id']]=self.ids.get(ad['id'],0)+1
        if tag=='script': self.in_script=True; self.attrs=ad; self.buf=[]
    def handle_endtag(self, tag):
        if tag=='script' and self.in_script:
            self.scripts.append((self.attrs,''.join(self.buf))); self.in_script=False
    def handle_data(self, data):
        if self.in_script: self.buf.append(data)

html=Path('ung-vien-tuyen-dung.html').read_text(encoding='utf-8', errors='replace')
p=Parser(); p.feed(html)
dup={k:v for k,v in p.ids.items() if v>1}
print('duplicate_ids', dup or 'none')
if dup: sys.exit(1)
errs=0
for idx,(attrs,code) in enumerate(p.scripts,1):
    if attrs.get('src') or not code.strip(): continue
    tmp=tempfile.NamedTemporaryFile('w',delete=False,suffix='.js',encoding='utf-8')
    tmp.write(code); tmp.close()
    cp=subprocess.run(['node','--check',tmp.name],capture_output=True,text=True)
    os.unlink(tmp.name)
    print('script',idx,'OK' if cp.returncode==0 else 'FAIL')
    if cp.returncode:
        print(cp.stderr.strip() or cp.stdout.strip()); errs+=1
if errs: sys.exit(1)

css=Path('assets/css/jobs.css').read_text(encoding='utf-8', errors='replace')
no_comments=re.sub(r'/\*.*?\*/','',css,flags=re.S)
no_strings=re.sub(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'','',no_comments)
bal=0; minbal=0
for ch in no_strings:
    if ch=='{': bal+=1
    elif ch=='}': bal-=1; minbal=min(minbal,bal)
print('css_balance', {'final':bal,'min':minbal})
if bal or minbal<0: sys.exit(1)

def z_for(selector):
    m=re.search(re.escape(selector)+r"\s*\{(?P<body>.*?)\}", css, re.S)
    if not m: return None
    z=re.search(r'z-index\s*:\s*(\d+)', m.group('body'))
    return int(z.group(1)) if z else None
