from html.parser import HTMLParser
from pathlib import Path
void={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class StackParser(HTMLParser):
    def __init__(self): super().__init__(); self.stack=[]; self.anomalies=[]
    def handle_starttag(self, tag, attrs):
        if tag not in void: self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in void: return
        if not self.stack:
            self.anomalies.append(('extra_close',tag)); return
        if self.stack[-1]==tag:
            self.stack.pop(); return
        # find recovery for common nesting
        if tag in self.stack:
            missed=[]
            while self.stack and self.stack[-1]!=tag:
                missed.append(self.stack.pop())
            if self.stack: self.stack.pop()
            self.anomalies.append(('auto_closed_before_'+tag, missed[:8]))
        else:
            self.anomalies.append(('unmatched_close',tag))
html=Path('nha-tuyen-dung.html').read_text(encoding='utf-8')
p=StackParser(); p.feed(html)
print('anomalies', p.anomalies[:20] or 'none')
print('remaining_stack_tail', p.stack[-20:])
# HTMLParser may report implied closes differently, fail on real anomalies only.
if p.anomalies or p.stack: raise SystemExit(1)
